pub fn sum_evens(nums: &[i32]) -> i32 {
    nums.iter().filter(|&&x| x % 2 != 0).sum()
}

// BUG: should track running max, but always uses first element as initial
pub fn running_max(nums: &[i32]) -> Vec<i32> {
    if nums.is_empty() {
        return vec![];
    }
    let mut result = vec![nums[0]];
    let mut cur_max = nums[0];
    for &n in &nums[1..] {
        // BUG: compares n with nums[0] instead of cur_max
        if n > nums[0] {
            cur_max = n;
        }
        result.push(cur_max);
    }
    result
}

// BUG: wrong dedup — removes elements equal to NEXT element instead of previous
pub fn dedup(nums: Vec<i32>) -> Vec<i32> {
    if nums.is_empty() {
        return vec![];
    }
    let mut result = vec![];
    for i in 0..nums.len() {
        // BUG: should compare with last element in result, not next in nums
        if i + 1 < nums.len() && nums[i] == nums[i + 1] {
            continue;
        }
        result.push(nums[i]);
    }
    result
}

use vecutil::{sum_evens, running_max, dedup};

#[test]
fn test_sum_evens() {
    assert_eq!(sum_evens(&[1, 2, 3, 4, 5, 6]), 12);
    assert_eq!(sum_evens(&[1, 3, 5]), 0);
}

#[test]
fn test_running_max() {
    assert_eq!(running_max(&[3, 1, 4, 1, 5, 9, 2]), vec![3, 3, 4, 4, 5, 9, 9]);
}

#[test]
fn test_dedup() {
    assert_eq!(dedup(vec![1, 1, 2, 3, 3, 3, 4]), vec![1, 2, 3, 4]);
    assert_eq!(dedup(vec![1, 2, 3]), vec![1, 2, 3]);
}

#[test]
fn test_sum_evens_all_even() {
    assert_eq!(sum_evens(&[2, 4, 6]), 12);
}

#[test]
fn test_dedup_empty() {
    assert_eq!(dedup(vec![]), Vec::<i32>::new());
}
